// ===== Code in JavaScript2 : validate 2 images + build Gemini request =====
// แอป (artwork_check/pairdiff.py) ส่ง POST form-urlencoded 2 ฟิลด์:
//   image_a_b64 = ภาพโซนของไฟล์หลัก (🅰) · image_b_b64 = ภาพโซนของไฟล์อ้างอิง (🅱)
// โหนดนี้ตรวจ base64/ชนิดภาพ แล้วประกอบ request ของ Gemini (temperature = 0)

const item = $input.first().json;
const body = item.body ?? item;

function clean(v) {
  let b64 = String(v ?? '').trim();
  const m = b64.match(/^data:image\/[a-z0-9.+-]+;base64,(.+)$/is);
  if (m) b64 = m[1];
  return b64.replace(/\s+/g, '').replace(/ /g, '+');
}
function mimeOf(b64) {
  const h = Buffer.from(b64.slice(0, 32), 'base64');
  if (h[0] === 0x89 && h[1] === 0x50 && h[2] === 0x4e) return 'image/png';
  if (h[0] === 0xff && h[1] === 0xd8) return 'image/jpeg';
  if (h[0] === 0x52 && h[1] === 0x49 && h[2] === 0x46 && h[8] === 0x57 && h[9] === 0x45) return 'image/webp';
  return null;
}

const a = clean(body.image_a_b64);
const b = clean(body.image_b_b64);
let valid = true;
let error = '';
const re64 = /^[A-Za-z0-9+/]+={0,2}$/;
for (const [name, v] of [['image_a_b64', a], ['image_b_b64', b]]) {
  if (!v) { valid = false; error = `missing form field '${name}'`; break; }
  if (v.length % 4 !== 0 || !re64.test(v)) { valid = false; error = `'${name}' is not valid base64`; break; }
}
const mimeA = valid ? mimeOf(a) : null;
const mimeB = valid ? mimeOf(b) : null;
if (valid && (!mimeA || !mimeB)) { valid = false; error = 'unsupported image format (expected JPEG / PNG / WebP)'; }
const sizeBytes = Math.floor((a.length + b.length) * 3 / 4);
if (valid && sizeBytes > 19 * 1024 * 1024) {
  valid = false;
  error = `images too large: ${(sizeBytes / 1048576).toFixed(1)} MB (limit ~19 MB)`;
}

const PROMPT = "You are a packaging quality-control inspector. You compare two images of the SAME printed label panel.\nIMAGE A = the approved artwork (reference design, usually a clean PDF render).\nIMAGE B = the version to check (a proof or a PHOTO of the printed pack; may have glare, perspective, texture).\nYour job is to find every place where B prints something different from A. Missing a real difference is the worst possible failure. The two images usually look almost the same - that is exactly why small differences are easy to miss.\n\nSTEP 1 - Transcribe IMAGE A into a_lines.\n- One array item per printed line, reading order top-to-bottom, left-to-right\n  (finish a column before starting the next one). Never merge two printed lines into one item.\n- Keep the spaces between words exactly as printed. Never glue two words together.\n- Verbatim: DO NOT correct spelling, grammar, capitalization, punctuation, digits or units.\n  Preserve decimal points, minus signs, <, >, %, superscripts and symbols (e.g. \"0.5g\", \"<1g\", \"-18°C\", \"®\").\n- Dot leaders (\".........\") are written as \"...\".\n- Text on curves/badges: transcribe it when legible.\n\nSTEP 2 - Transcribe IMAGE B into b_lines, from the PIXELS OF IMAGE B ONLY.\n- Same rules as STEP 1.\n- NEVER copy a line from a_lines. Before writing each line of B, look at that line in image B again.\n- A line of B that looks like a line of A is NOT evidence that they are identical. Check every character of B,\n  especially: letter case (C vs c), word endings (Breeds vs Breed), spelling variants (Sulfate vs Sulphate),\n  digits (1/7, 0/8, 5/6), decimal points, hyphens, and extra or missing words.\n- If some characters of B are not legible, write [?] in their place. Never fill them in from A.\n\nSTEP 3 - Compare line by line and list EVERY difference.\n- For each line of b_lines find the matching line of a_lines and compare them character by character,\n  INCLUDING LETTER CASE. Also report lines of A missing from B and lines of B missing from A.\n- Examples of real differences: \"D-Calcium\" vs \"D-calcium\", \"Breeds\" vs \"Breed\",\n  \"Copper Sulfate\" vs \"Copper Sulphate\", \"1g\" vs \"7g\", \"1.5g\" vs \"15g\".\n- Report ALL differences. Do not stop after a few.\n- \"a\" and \"b\": quote the differing text EXACTLY as it appears in your a_lines / b_lines\n  (shortest span that shows the difference, e.g. a=\"1g\" b=\"7g\"). Use \"\" when absent on that side.\n- kind: \"number\" if digits/units/decimals/signs are involved, \"text\" for words/letters/case/\n  punctuation, \"visual\" for non-text differences (font weight, colour, logo, symbol, barcode\n  bars, layout) - for visual use a=\"\" b=\"\" and describe it in \"where\".\n- \"where\": short location hint (e.g. \"Total Fat row\", \"2nd paragraph\").\n- DO NOT report differences caused only by line wrapping, image quality, glare, perspective,\n  resolution, or the part of the image outside the label panel.\n- If the two panels are identical, return an empty differences array.\n\nReturn ONLY JSON matching the schema.";

const responseSchema = {
  type: 'OBJECT',
  properties: {
    // รายการบรรทัด (ไม่ใช่สตริงเดียว) — v1 ได้ทั้งแผงเป็นก้อนเดียว ไม่มีขึ้นบรรทัด คำติดกัน
    a_lines: { type: 'ARRAY', items: { type: 'STRING' } },
    b_lines: { type: 'ARRAY', items: { type: 'STRING' } },
    differences: {
      type: 'ARRAY',
      items: {
        type: 'OBJECT',
        properties: {
          a: { type: 'STRING' },
          b: { type: 'STRING' },
          kind: { type: 'STRING', enum: ['text', 'number', 'visual'] },
          where: { type: 'STRING' },
        },
        required: ['a', 'b', 'kind'],
      },
    },
  },
  // ถอดความ "ก่อน" เทียบ — โมเดลเขียนตามลำดับนี้
  propertyOrdering: ['a_lines', 'b_lines', 'differences'],
  required: ['a_lines', 'b_lines', 'differences'],
};

const geminiRequest = !valid ? null : {
  contents: [{
    role: 'user',
    parts: [
      { text: PROMPT },
      { text: 'IMAGE A (approved artwork):' },
      { inlineData: { mimeType: mimeA, data: a } },
      { text: 'IMAGE B (version to check):' },
      { inlineData: { mimeType: mimeB, data: b } },
    ],
  }],
  generationConfig: {
    temperature: 0,          // ห้ามแก้ — ต้องวัดซ้ำได้
    topP: 1,
    maxOutputTokens: 24576,
    responseMimeType: 'application/json',
    responseSchema,
    // งานเทียบต้อง "คิด" — 1024 ถูกใช้หมดเกลี้ยงบนงานจริง (thoughtsTokenCount 1023)
    // (ลบบรรทัดนี้ถ้ารุ่นที่ใช้ไม่รองรับ)
    thinkingConfig: { thinkingBudget: 4096 },
  },
};

return [{ json: { valid, error, size_kb: Math.round(sizeBytes / 102.4) / 10, gemini_request: geminiRequest } }];

// ===== Code in JavaScript : parse Gemini response → app contract =====
// แอปคาดหวัง: {"a_text": "...", "b_text": "...", "differences": [...], "engine": "..."}
// ⚠️ ห้ามคืนคำตอบว่าง — แอปถือว่า "ว่าง = ล้มเหลว" แล้วยิงซ้ำ
const r = $input.first().json;
if (r.error) {
  throw new Error(`Gemini API error: ${JSON.stringify(r.error)}`);
}
const cand = (r.candidates ?? [])[0] ?? {};
const finishReason = cand.finishReason ?? '';
const raw = ((cand.content ?? {}).parts ?? []).map((p) => p.text ?? '').join('\n').trim();
let s = raw.replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/, '').trim();
let parsed = null;
try { parsed = JSON.parse(s); } catch (e) {
  const i = s.indexOf('{'); const j = s.lastIndexOf('}');
  if (i >= 0 && j > i) { try { parsed = JSON.parse(s.slice(i, j + 1)); } catch (e2) { /* noop */ } }
}
const out = { a_text: '', b_text: '', differences: [], engine: 'gemini-2.5-flash' };
// รายการบรรทัด → ข้อความหลายบรรทัด (สัญญากับแอปเดิม: a_text / b_text)
// รับ a_text แบบสตริงด้วย เผื่อโมเดลตอบตาม schema เก่า
function joinLines(lines, text) {
  if (Array.isArray(lines)) {
    return lines.filter((s) => typeof s === 'string').map((s) => s.trim()).filter(Boolean).join('\n');
  }
  return typeof text === 'string' ? text : '';
}
if (parsed && typeof parsed === 'object') {
  out.a_text = joinLines(parsed.a_lines, parsed.a_text);
  out.b_text = joinLines(parsed.b_lines, parsed.b_text);
  out.differences = Array.isArray(parsed.differences) ? parsed.differences : [];
}
if (!out.a_text || !out.b_text) {
  out.error = `incomplete answer (finishReason=${finishReason || 'unknown'})`;
}
if (finishReason && finishReason !== 'STOP') {
  out.warning = `finishReason=${finishReason}`;
}
out.usage = r.usageMetadata ?? null;
return [{ json: out }];
